with enriched as (select *, avg(age) over (order by signup_date, id rows between 2 preceding and 1 preceding) as age_avg_2_prior, corr(credit_limit, age) over (partition by city) as corr_credit_limit_age, max(age) over (partition by country) as country_max_age from customers where city = 'Chiang Mai') select id, name, email, city, segment, is_active, credit_limit, age, country_max_age, case when segment rlike '^(Corporate|Consumer)$' then 'EXTENDED' when segment rlike '^(SMB)$' then 'OTHER_ZONE' else 'GROUP_B' end as segment_zone from enriched order by credit_limit desc nulls last, segment
